function translatePageText(locale: Locale, text: string): string {
  if (locale === "en") return text;
  const message = Object.entries(messages.en).find(([, value]) => value === text);
  if (message) return messages[locale][message[0] as keyof typeof messages.en] || text;
  return pageTranslations[locale][text] || extendedTranslations[locale][text] || componentTranslations[locale][text] || foodTranslations[locale][text] || contentTranslations[locale][text] || text;
}

type LocaleContextValue = { locale: Locale; setLocale: (locale: Locale) => void; t: (key: keyof typeof messages.en) => string; tr: (text: string) => string };
const LocaleContext = createContext<LocaleContextValue | null>(null);

function initialLocale(): Locale {
  try {
    const value = localStorage.getItem(LOCALE_KEY);
    return value === "hi" || value === "kn" ? value : "en";
  } catch { return "en"; }
}

export function LocaleProvider({ children }: { children: ReactNode }) {
  const [locale, setLocaleState] = useState<Locale>(initialLocale);
  const setLocale = (next: Locale) => setLocaleState(next);
  useEffect(() => {
    try { localStorage.setItem(LOCALE_KEY, locale); } catch { /* storage is optional */ }
    document.documentElement.lang = locale;
  }, [locale]);
  const value = useMemo(() => ({ locale, setLocale, t: (key: keyof typeof messages.en) => messages[locale][key] || messages.en[key], tr: (text: string) => translatePageText(locale, text) }), [locale]);
  return <LocaleContext.Provider value={value}>{children}</LocaleContext.Provider>;
}

export function useLocale() {
  const context = useContext(LocaleContext);
  if (!context) throw new Error("useLocale must be used inside LocaleProvider");
  return context;
}

export function LanguageSelect({ compact = false }: { compact?: boolean }) {
  const { locale, setLocale, t } = useLocale();
  return (
    <label className={`language-select${compact ? " compact" : ""}`}>
      <span>{compact ? t("appLanguage") : t("language")}</span>
      <select aria-label={t("language")} value={locale} onChange={(event) => setLocale(event.target.value as Locale)}>
        <option value="en">{t("english")}</option>
        <option value="hi">{t("hindi")}</option>
        <option value="kn">{t("kannada")}</option>
      </select>
    </label>
  );
}
